ettings['instagram_url']??'https://www.instagram.com/wcudc_ecsf')?>"></label><label>Facebook<input name="setting[facebook_url]" value="<?=e($settings['facebook_url']??'https://www.facebook.com/Duramecampusfellowshi')?>"></label><label>Google Maps URL<input name="setting[map_url]" value="<?=e($settings['map_url']??'https://www.google.com/maps/search/?api=1&query=Wachemo+University+Durame+Campus')?>"></label><label>Service Registration URL<input name="setting[service_form_url]" value="<?=e($settings['service_form_url']??service_url())?>"></label></div><button class="btn primary">Save Settings</button></form></div><?php admin_end(); ?>
